int xc2028_set_config(struct dvb_frontend *fe, void *priv_cfg)
{
    struct xc2028_data *priv = fe->demodulator_priv;
    struct xc2028_config *cfg = priv_cfg;
    int ret = 0;

    mutex_lock(&priv->lock);

    /* Copy configuration data */
    memcpy(&priv->config, cfg, sizeof(*cfg));

    /* Check if firmware name has changed */
    if (priv->fw_name && strcmp(priv->fw_name, cfg->firmware_name)) {
        kfree(priv->fw_name);
        priv->fw_name = kstrdup(cfg->firmware_name, GFP_KERNEL);
        if (!priv->fw_name) {
            ret = -ENOMEM;
            goto error;
        }

        /* Request firmware if no firmware is loaded */
        if (priv->state == XC2028_STATE_IDLE) {
            ret = request_firmware_nowait(
                THIS_MODULE,
                1,
                priv->fw_name,
                &fe->dvb->pub_desc->adapter->dev,
                GFP_KERNEL,
                priv,
                xc2028_firmware_cb);
            if (ret < 0)
                goto error;
        }
    }

    mutex_unlock(&priv->lock);
    return ret;

error:
    mutex_unlock(&priv->lock);
    return ret;
}

int xc2028_set_config(struct dvb_frontend *fe, void *priv_cfg)
{
    struct xc2028_data *cfg = (struct xc2028_data *)priv_cfg;
    int result = 0;

    mutex_lock(&fe->lock);

    /* Copy configuration data */
    memcpy(&fe->demodulator_priv, cfg, sizeof(struct xc2028_data));

    /* Check if firmware name has changed */
    if (strcmp(fe->demodulator_priv.firmware_name, cfg->firmware_name) != 0) {
        kfree(fe->demodulator_priv.firmware_name);
        fe->demodulator_priv.firmware_name = kstrdup(cfg->firmware_name, GFP_KERNEL);
        if (!fe->demodulator_priv.firmware_name) {
            mutex_unlock(&fe->lock);
            return -ENOMEM;
        }

        /* Check if firmware needs to be reloaded */
        if (fe->state == FIRMWARE_NOT_LOADED) {
            result = request_firmware_nowait(THIS_MODULE, 1,
                                             fe->demodulator_priv.firmware_name,
                                             &fe->dvb->priv->i2c_adap, GFP_KERNEL,
                                             fe, xc2028_firmware_cb);
            if (result < 0) {
                mutex_unlock(&fe->lock);
                return result;
            }
        }
    }

    mutex_unlock(&fe->lock);
    return result;
}

