int xc2028_set_config(struct dvb_frontend *fe, void *priv_cfg)
{
    struct xc2028_data *cfg = (struct xc2028_data *)priv_cfg;
    int result = 0;

    mutex_lock(&fe->lock);

    /* Copy configuration data */
    memcpy(&fe->dvb->priv, cfg, sizeof(struct xc2028_data));

    if (fe->dvb->firmware && strcmp(fe->dvb->firmware, cfg->firmware_name) != 0) {
        kfree(fe->dvb->firmware);
        fe->dvb->firmware = NULL;
    }

    if (!fe->dvb->firmware) {
        fe->dvb->firmware = kmalloc(strlen(cfg->firmware_name) + 1, GFP_KERNEL);
        if (!fe->dvb->firmware) {
            result = -ENOMEM;
            goto unlock_mutex;
        }
        strcpy(fe->dvb->firmware, cfg->firmware_name);
        result = request_firmware_nowait(
            THIS_MODULE, 1,
            fe->dvb->firmware,
            fe->dvb->device,
            GFP_KERNEL,
            (void *)fe,
            xc2028_firmware_cb
        );
        if (result < 0)
            goto unlock_mutex;
    }

unlock_mutex:
    mutex_unlock(&fe->dvb->lock);
    return result;
}

int xc2028_set_config(struct dvb_frontend *fe, void *priv_cfg)
{
    struct xc2028_data *cfg = priv_cfg;
    int ret = 0;

    mutex_lock(&fe->lock);

    if (strcmp(cfg->firmware_name, fe->dvb->priv) != 0) {
        kfree(fe->dvb->priv);
        fe->dvb->priv = kstrdup(cfg->firmware_name, GFP_KERNEL);
        if (!fe->dvb->priv) {
            ret = -ENOMEM;
            mutex_unlock(&fe->lock);
            return ret;
        }
    }

    if (fe->state == FIRMWARE_REQUESTED) {
        ret = request_firmware_nowait(fe->dvb->device, 1, fe->dvb->priv,
                                      fe->dvb->device, GFP_KERNEL,
                                      &cfg->firmware_cb, fe);
        if (ret < 0) {
            mutex_unlock(&fe->lock);
            return ret;
        }
    }

    mutex_unlock(&fe->lock);
    return ret;
}
